CREATE TRIGGER [BEConfig_insert_trigger] ON [BEConfig] FOR INSERT AS
UPDATE [side] SET [sync_row_is_tombstone] = 0, [local_update_peer_key] = 0, [restore_timestamp] = NULL, [update_scope_local_id] = NULL, [last_change_datetime] = GETDATE() FROM [BEConfig_tracking] [side] JOIN INSERTED AS [i] ON [side].[Macaddress] = [i].[Macaddress]
INSERT INTO [BEConfig_tracking] ([i].[Macaddress], [create_scope_local_id], [local_create_peer_key], [local_create_peer_timestamp], [update_scope_local_id], [local_update_peer_key], [sync_row_is_tombstone], [last_change_datetime], [restore_timestamp]) SELECT [i].[Macaddress], NULL, 0, @@DBTS+1, NULL, 0, 0, GETDATE() , NULL FROM INSERTED AS [i] LEFT JOIN [BEConfig_tracking] [side] ON [side].[Macaddress] = [i].[Macaddress] WHERE [side].[Macaddress] IS NULL
